// extract out the base rating contribution to the base stat to get the true base (baseAdj)
const base = GetStat(GetOwner(), $#10516612381411111:109343399106255$);
const baseRating = GetStat(GetInstigator(), $#10516612381411111:6064628617694478341$);
const baseCoeff = EvalE($#10516612381411112:6064634020100112433$);
const mult = EvalE($#10516612381411112:6064632412936667141$);
const baseAdj = base - baseRating / (baseRating * mult + baseCoeff);

// calculate total rating including the base rating but reduced by the coefficient quotient
const coeff = EvalE($#10516612381411112:6064632412892102657$);
const rating = baseRating * coeff/baseCoeff + GetStat(GetInstigator(), $#10516612381411111:109343183951492$);

// calc final stat value
baseAdj + rating / (rating * mult + coeff)
